private JsonNode readUntilUpdate(String type) throws Exception {
    while (true) {
        JsonNode value = MAPPER.readTree(reader.readLine());
        JsonNode update = value.path("params").path("update");
        if (type.equals(update.path("sessionUpdate").asText())) return update;
    }
}

private List<JsonNode> updatesUntilIdle() throws Exception {
